fun tr(language: String, key: String): String = when (language.lowercase()) {
    "en" -> english[key] ?: ukrainian[key] ?: key
    "ru" -> russian[key] ?: ukrainian[key] ?: key
    else -> ukrainian[key] ?: key
}
